import inspect

import torch
from flask import Flask, jsonify, request
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_DIR)
model.eval()


def _label_index(name):
    """Map 'positive'/'negative' onto the model's own label ordering."""
    id2label = getattr(model.config, "id2label", None) or {}
    for idx, label in id2label.items():
        if str(label).lower().endswith(name):
            return int(idx)
    return 1 if name == "positive" else 0


POS_IDX = _label_index("positive")
NEG_IDX = _label_index("negative")


def _tokenize(text):
    kwargs = {"return_tensors": "pt", "truncation": True, "padding": True}
    max_len = getattr(tokenizer, "model_max_length", 512) or 512
    kwargs["max_length"] = min(int(max_len), 512)
    try:
        params = inspect.signature(tokenizer.__call__).parameters
        if "max_length" not in params and not any(
            p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()
        ):
            kwargs.pop("max_length")
    except (ValueError, TypeError):
        pass
    try:
        return tokenizer(text, **kwargs)
    except TypeError:
        kwargs.pop("max_length", None)
        return tokenizer(text, **kwargs)


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be JSON with a 'text' field"}), 400
    if "text" not in data:
        return jsonify({"error": "Missing required field 'text'"}), 400
    text = data["text"]
    if not isinstance(text, str) or not text.strip():
        return jsonify({"error": "Field 'text' must be a non-empty string"}), 400

    try:
        inputs = _tokenize(text)
        with torch.no_grad():
            output = model(**inputs)
        logits = output.logits if hasattr(output, "logits") else output[0]
        probs = torch.nn.functional.softmax(logits, dim=-1)[0]
        pos = float(probs[POS_IDX])
        neg = float(probs[NEG_IDX])
    except Exception as exc:  # noqa: BLE001
        return jsonify({"error": "Inference failed: {}".format(exc)}), 400

    return jsonify(
        {
            "sentiment": "positive" if pos >= neg else "negative",
            "confidence": {"positive": pos, "negative": neg},
        }
    )


@app.errorhandler(400)
def _bad_request(err):
    return jsonify({"error": "Bad request"}), 400


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, threaded=True)
